<script setup lang="ts">
import AppButton from './components/AppButton.vue'
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {Scissors,Layers,Settings2,HardDrive,Plus,FileVideo,Link,FolderOpen,X,RefreshCw,LoaderCircle} from '@lucide/vue'
import {api} from './api'
import type {Project,Config,Job,Transcript,Revision,Decision,AnalysisView,AnalysisSelection} from './types'
import {active} from './format'
import ProjectLibrary from './components/ProjectLibrary.vue'
import ProjectWorkspace from './components/ProjectWorkspace.vue'
import SettingsPanel from './components/SettingsPanel.vue'
import AppToaster from './components/AppToaster.vue'
import {notify,createJobNotifier} from './notifications'
const projects=ref<Project[]>([]),config=ref<Config|null>(null),jobs=ref<Job[]>([]),project=ref<Project|null>(null),transcript=ref<Transcript|null>(null),revisions=ref<Revision[]>([])
const setupMissing=computed(()=>!config.value||!config.value.asr_available||!config.value.tools_available||!config.value.gemini_key_configured)
const page=ref('projects'),sourceUrl=ref(''),previewUrl=ref(''),busy=ref(false),initial=ref(true),offline=ref(false),dialog=ref<HTMLDialogElement>(),analysisDialog=ref<HTMLDialogElement>()
const selectedRevision=ref(''),mediaLoading=ref(false),analysis=ref<AnalysisView|null>(null),selection=ref<AnalysisSelection|null>(null)
let selectionWrite=Promise.resolve()
async function saveSelection(value:AnalysisSelection){const pid=project.value?.id;if(!pid)return;selectionWrite=selectionWrite.then(async()=>{try{const saved=await api.saveSelection(pid,value);if(project.value?.id===pid)selection.value=saved}catch(e){notify.error((e as Error).message)}})}
async function generateSelected(value:{analysis_hash:string;candidate_ids:string[]}){await selectionWrite;await start('render',value)}
const covers=ref<Record<string,string>>({}),trashDialog=ref<HTMLDialogElement>(),trashRows=ref<{id:string;name:string}[]>([]),trashKind=ref<'projects'|'cuts'>('projects')
const coverPending=new Set<string>()
async function loadCover(row:Project){if(!row.source||covers.value[row.id]||coverPending.has(row.id))return;coverPending.add(row.id);try{covers.value[row.id]=await api.media(row.id,'thumbnail')}catch{}finally{coverPending.delete(row.id)}}
async function deleteProject(id:string){const row=projects.value.find(p=>p.id===id);if(!confirm('Mover '+(row?.title||row?.name||'projeto')+' para a lixeira? O original será preservado.'))return;await action(async()=>{await api.deleteProject(id);if(project.value?.id===id){project.value=null;++generation};delete covers.value[id];await refresh()})}
async function deleteClip(id:string){if(!project.value||!confirm('Mover este corte para a lixeira? Ele deixará de participar das exportações.'))return;const pid=project.value.id;await action(async()=>{await api.deleteClip(pid,id);await openProject(pid)})}
async function showTrash(kind:'projects'|'cuts'){await action(async()=>{trashKind.value=kind;trashRows.value=kind==='projects'?await api.trash():project.value?(await api.deletedClips(project.value.id)).map(r=>({id:r.revision_id,name:r.title})):[];trashDialog.value?.showModal()})}
async function restore(id:string){await action(async()=>{if(trashKind.value==='projects')await api.restoreProject(id);else if(project.value)await api.restoreClip(project.value.id,id);trashRows.value=trashRows.value.filter(r=>r.id!==id);await refresh();if(project.value)await openProject(project.value.id)})}

const newName=ref(''),sourceInput=ref(''),sourceKind=ref('file'),windowSeconds=ref(600)
const reportJobs=createJobNotifier();let connectionFailed=false,connectionEpoch=0
let timer:ReturnType<typeof setInterval>|undefined;let refreshing=false;let generation=0
const projectJobs=computed(()=>jobs.value.filter(j=>j.project_id===project.value?.id)),running=computed(()=>jobs.value.some(j=>active(j.status)))
function navigate(destination:string){++generation;project.value=null;page.value=destination}
async function action(fn:()=>Promise<unknown>,success=''){if(busy.value)return;busy.value=true;try{await fn();if(success)notify.success(success)}catch(e){notify.error((e as Error).message)}finally{busy.value=false}}
async function refresh(){if(refreshing)return;refreshing=true;try{
  const [rows,tasks]=await Promise.all([api.projects(),api.jobs()]);projects.value=rows;for(const row of rows)void loadCover(row)
  const previous=jobs.value; jobs.value=tasks;reportJobs(tasks);offline.value=false;connectionFailed=false
  if(project.value){const latest=rows.find(p=>p.id===project.value?.id)
    const available=latest&&((!project.value.source&&!!latest.source)||(!project.value.has_transcript&&latest.has_transcript))
    if(latest)project.value=latest
    const finished=tasks.some(j=>j.project_id===project.value?.id&&['completed','failed','cancelled','interrupted'].includes(j.status)&&previous.find(p=>p.id===j.id)?.status!==j.status)
    if(finished||available)await openProject(project.value.id)
    else {const pid=project.value.id;const guard=generation;const [a,r]=await Promise.allSettled([api.analysis(pid),api.revisions(pid)]);if(project.value?.id===pid&&guard===generation){if(a.status==='fulfilled')analysis.value=a.value;if(r.status==='fulfilled')revisions.value=r.value}}
  }
}catch(e){offline.value=true;if(!connectionFailed)connectionEpoch++;connectionFailed=true;notify.error((e as Error).message,{key:'connection:'+connectionEpoch})}finally{refreshing=false}}
async function openProject(id:string){const same=project.value?.id===id;const prior=same?selectedRevision.value:'';const current=++generation;const detail=await api.project(id);if(current!==generation)return
  project.value=detail;page.value='projects';if(!same){transcript.value=null;revisions.value=[];sourceUrl.value='';previewUrl.value='';analysis.value=null;selection.value=null}
  mediaLoading.value=true
  const [t,r,s]=await Promise.allSettled([detail.has_transcript?api.transcript(id):Promise.resolve(null),api.revisions(id),detail.source?api.media(id,'source'):Promise.resolve('')])
  if(current!==generation)return
  transcript.value=t.status==='fulfilled'?t.value:null;revisions.value=r.status==='fulfilled'?r.value:[];sourceUrl.value=s.status==='fulfilled'?s.value:''
  if([t,r,s].some(item=>item.status==='rejected'))notify.warning('Alguns artefatos estão indisponíveis. O vídeo e a transcrição válidos continuam acessíveis.',{key:'artifacts:'+id})
  selectedRevision.value=revisions.value.some(row=>row.revision_id===prior)?prior:revisions.value[0]?.revision_id||''
  const [a,sel]=await Promise.allSettled([api.analysis(id),api.selection(id)]);if(current!==generation)return;if(a.status==='fulfilled')analysis.value=a.value;else notify.warning('Não foi possível carregar a análise salva.',{key:'analysis-load:'+id});if(sel.status==='fulfilled')selection.value=sel.value;else notify.warning('Não foi possível carregar a seleção de trechos.',{key:'selection-load:'+id})
  if(detail.is_manual){const url=await api.media(id,'manual').catch(()=> '');if(current===generation)previewUrl.value=url}
  else if(selectedRevision.value)await selectClip(selectedRevision.value)
  if(current===generation)mediaLoading.value=false
}
async function importProject(){await action(async()=>{const path=await api.pick('project');if(!path)return;const row=await api.importProject(path);await refresh();await openProject(row.id)})}
async function pickVideo(){await action(async()=>{const path=await api.pick('video');if(path){sourceInput.value=path;if(!newName.value)newName.value=path.split(/[\\/]/).pop()?.replace(/\.[^.]+$/,'')||'Novo projeto'}})}
async function create(){await action(async()=>{const value=await api.create(newName.value.trim(),sourceInput.value.trim(),{automatic:!setupMissing.value});dialog.value?.close();newName.value='';sourceInput.value='';await refresh();await openProject(value.project.id)})}
function showCreate(){newName.value='';sourceInput.value='';sourceKind.value='file';dialog.value?.showModal()}
function showAnalysis(){windowSeconds.value=config.value?.window_seconds||600;analysisDialog.value?.showModal()}
async function start(operation:string,options:Record<string,unknown>={}){await action(async()=>{if(!project.value)return;await api.start(project.value.id,operation,options);analysisDialog.value?.close();await refresh()},'Tarefa iniciada. Acompanhe em Preparar seus cortes.')}
async function review(decision:Decision){await action(async()=>{if(!project.value)return;await api.decide(project.value.id,decision);await openProject(project.value.id)},decision.decision==='approved'?'Corte aprovado para esta revisão.':'Corte rejeitado.')}
async function selectClip(id:string){if(!project.value)return;const pid=project.value.id;const current=generation;selectedRevision.value=id;previewUrl.value='';mediaLoading.value=true
  const url=await api.media(pid,id).catch(()=>{notify.error('Não foi possível abrir esta prévia.',{key:'preview:'+pid+':'+id});return ''})
  if(project.value?.id===pid&&current===generation&&selectedRevision.value===id){previewUrl.value=url;mediaLoading.value=false}
}
async function saveConfig(value:Config){config.value=await api.saveConfig(value)}
async function saveKey(key:string){const result=await api.saveKey(key);config.value=await api.config();return result}
async function closeService(){await action(async()=>{await api.shutdown();if(timer)clearInterval(timer);offline.value=true;notify.info('Serviço encerrado. Abra novamente pelo atalho para continuar.')})}
async function openFolder(){await action(async()=>{if(project.value)await api.openFolder(project.value.id)})}
async function cancelJob(id:string){await action(async()=>{await api.cancel(id);await refresh()})}
async function replaceSource(id:string){await action(async()=>{const path=await api.pick('video');if(!path)return;await api.resume(id,{source_input:path});await refresh();notify.success('Arquivo selecionado. A preparação será retomada neste projeto.')})}
async function resumeJob(id:string){await action(async()=>{await api.resume(id);await refresh()})}
onMounted(async()=>{try{await Promise.all([refresh(),api.config().then(value=>config.value=value)])}catch(e){notify.error((e as Error).message)}finally{initial.value=false};timer=setInterval(refresh,3000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
  <div class="app-shell"><aside class="sidebar"><a class="brand" href="#" @click.prevent="navigate('projects')"><span class="brand-symbol"><Scissors :size="23"/></span><span>AutoClip<small>Seu espaço de edição</small></span></a><AppButton class="sidebar-create" @click="showCreate" :disabled="busy||initial||running"><Plus :size="17"/>Novo projeto</AppButton><nav aria-label="Navegação principal"><AppButton :class="{selected:page==='projects'}" @click="navigate('projects')"><Layers :size="19"/>Projetos<span>{{projects.length}}</span></AppButton><AppButton :class="{selected:page==='settings'}" @click="navigate('settings')"><Settings2 :size="19"/>Configurações</AppButton></nav><div class="sidebar-bottom"><div class="sidebar-session"><span class="app-context">{{project?'Área de trabalho':page==='settings'?'Preferências':'Área de trabalho'}}</span><span class="session-info"><span class="local-dot" :class="{offline}"></span>{{offline?'Sem conexão':'Sessão local'}}<AppButton class="icon-button" title="Atualizar projetos" @click="action(refresh)"><RefreshCw :size="15"/></AppButton></span></div><div class="engine-status"><span class="local-dot" :class="{offline:offline}"></span><div><strong>Motor local</strong><small>Transcrição e render em CPU</small></div><HardDrive :size="16"/></div><p>Seus arquivos, no seu computador.</p><AppButton class="text-button" @click="closeService" :disabled="busy||running" title="Disponível quando nenhuma tarefa estiver em execução">Encerrar serviço</AppButton></div></aside>
    <main class="main-content"><div class="page-content"><div v-if="initial" class="loading-state"><LoaderCircle class="spin" :size="25"/><p>Abrindo seus projetos…</p></div><template v-else><section v-if="setupMissing&&!project&&page==='projects'" class="readiness-panel"><div><h2>Prepare seu espaço de edição</h2><p>Confira os recursos antes de iniciar o processamento automático.</p><div class="readiness-items"><span>{{config?.asr_available?'Transcrição disponível':'Localizar modelo Whisper'}}</span><span>{{config?.tools_available?'Vídeo disponível':'Localizar FFmpeg e ffprobe'}}</span><span>{{config?.gemini_key_configured?'Chave salva · validar em Configurações':'Adicionar chave Gemini'}}</span></div></div><AppButton class="button primary" @click="navigate('settings')">Configurar processamento</AppButton></section><Transition name="screen"><div :key="project?.id||page" class="screen-content"><SettingsPanel v-if="page==='settings'&&config" :config="config" :save-config="saveConfig" :save-key="saveKey" :get-connection="api.geminiConnection" :test-connection="api.testGemini" :pick="api.pick"/><ProjectWorkspace v-else-if="project" :key="project.id" :project="project" :transcript="transcript" :revisions="revisions" :jobs="projectJobs" :source-url="sourceUrl" :preview-url="previewUrl" :selected-revision="selectedRevision" :media-loading="mediaLoading" :busy="busy" :analysis="analysis" :selection="selection" @selection="saveSelection" @back="navigate('projects')" @folder="openFolder" @transcribe="start('transcribe')" @analyze="showAnalysis" @render="generateSelected" @cancel="cancelJob($event)" @resume="resumeJob($event)" @replace-source="replaceSource($event)" @select="selectClip" @decision="review" @export="start('export')" @delete="deleteClip" @deleted="showTrash('cuts')"/><ProjectLibrary v-else :covers="covers" :projects="projects" :busy="busy" :active-projects="jobs.filter(j=>active(j.status)).map(j=>j.project_id)" @open="action(()=>openProject($event))" @create="showCreate" @import="importProject" @delete="deleteProject" @trash="showTrash('projects')"/></div></Transition></template></div></main>
  </div>
  <AppToaster/>
  <dialog ref="dialog" class="modal"><form @submit.prevent="create"><header><div><h2>Novo projeto</h2><p>Comece com um vídeo. O original será preservado.</p></div><AppButton type="button" class="icon-button" title="Fechar" @click="dialog?.close()"><X :size="19"/></AppButton></header><div class="source-switch"><AppButton type="button" :class="{selected:sourceKind==='file'}" @click="sourceKind='file';sourceInput=''"><FileVideo :size="17"/>Arquivo local</AppButton><AppButton type="button" :class="{selected:sourceKind==='url'}" @click="sourceKind='url';sourceInput=''"><Link :size="17"/>Link do YouTube</AppButton></div><div v-if="sourceKind==='file'" class="file-drop"><FileVideo :size="32"/><p>{{sourceInput?sourceInput.split(/[\\/]/).pop():'Escolha um vídeo do seu computador'}}</p><AppButton type="button" class="button secondary" :disabled="busy" @click="pickVideo"><FolderOpen :size="16"/>Selecionar vídeo</AppButton></div><label v-else class="field">URL do vídeo<input type="url" v-model="sourceInput" placeholder="https://www.youtube.com/watch?v=..." required/><small>Use conteúdo autorizado para processamento.</small></label><label class="field">Nome do projeto<input v-model="newName" placeholder="Ex.: Entrevista sobre educação" maxlength="100" required/></label><div class="analysis-summary"><strong>{{setupMissing?'Importar vídeo · concluir configuração depois':'Importar → Transcrever → Analisar'}}</strong><span>{{config?.gemini_model}} · preferência {{config?.clip_preferred_seconds||60}} s · máximo {{config?.clip_max_seconds||180}} s</span><span>Geração de prévias manual · {{config?.pause_mode==='preserve'?'pausas preservadas':'redução conservadora de pausas'}}</span></div><p v-if="!setupMissing" class="subtle">A transcrição será analisada automaticamente pelo Gemini. As chamadas são dimensionadas pelo conteúdo; a API pode gerar custos.</p><div v-if="setupMissing" class="readiness-items"><span>Configuração incompleta para o processamento automático.</span><AppButton type="button" class="button secondary" @click="dialog?.close();navigate('settings')">Abrir configurações</AppButton></div><footer><AppButton type="button" class="button secondary" @click="dialog?.close()">Cancelar</AppButton><AppButton class="button primary" :disabled="busy||running||!sourceInput.trim()||!newName.trim()||!config?.tools_available"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{setupMissing?'Importar vídeo':'Criar projeto'}}</AppButton></footer></form></dialog>
  <dialog ref="trashDialog" class="modal"><div class="trash-content"><header><h2>{{trashKind==='projects'?'Lixeira de projetos':'Lixeira de cortes'}}</h2><AppButton class="icon-button" title="Fechar lixeira" @click="trashDialog?.close()"><X :size="19"/></AppButton></header><p class="subtle">Arquivos preservados. Restaure para voltar a usar.</p><p v-if="!trashRows.length">A lixeira está vazia.</p><div v-for="row in trashRows" :key="row.id" class="trash-row"><strong>{{row.name}}</strong><AppButton class="button small secondary" :disabled="busy||running" @click="restore(row.id)">Restaurar</AppButton></div></div></dialog>
  <dialog ref="analysisDialog" class="modal"><form @submit.prevent="start('analyze',{window_seconds:windowSeconds,max_text_chars:config?.max_text_chars||60000})"><header><div><h2>Analisar com Gemini</h2><p>O motor organiza as chamadas para analisar toda a transcrição.</p></div><AppButton type="button" class="icon-button" title="Fechar" @click="analysisDialog?.close()"><X :size="19"/></AppButton></header><div class="analysis-summary"><strong>{{config?.gemini_model}}</strong><span>Preferência {{config?.clip_preferred_seconds||60}} s · máximo {{config?.clip_max_seconds||180}} s · {{config?.show_thought_summaries===false?'resumos desativados':'resumos da API quando disponíveis'}}</span><span>{{project?.word_count.toLocaleString('pt-BR')}} palavras disponíveis</span></div><details class="analysis-advanced"><summary>Ajustes avançados</summary><label class="field">Janela em segundos<input type="number" v-model.number="windowSeconds" min="60" max="1800" required/><small>Quantidade de transcrição por solicitação. Pode manter o padrão; não define o tamanho dos cortes.</small></label></details><p class="subtle">A transcrição em texto será enviada ao Gemini. Chamadas automáticas conforme o conteúdo, com novas tentativas para falhas recuperáveis. Você pode cancelar; a API pode gerar custos.</p><div v-if="!config?.gemini_key_configured" class="subtle">Configure sua chave Gemini nas configurações primeiro.</div><footer><AppButton type="button" class="button secondary" @click="analysisDialog?.close()">Cancelar</AppButton><AppButton class="button primary" :disabled="busy||!config?.gemini_key_configured||running">Iniciar análise</AppButton></footer></form></dialog>
</template>
